import { test, expect } from '@playwright/test';

test.describe('Background Sync Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/sync-page');
  });

  test('should display toast notification when background sync completes successfully', async ({ page }) => {
    // Setup: intercept the API call for background sync
    await page.route('**/api/sync/background', (route) => {
      route.continue();
    });

    // Verify toast container exists
    const toastContainer = page.getByRole('status');
    await expect(toastContainer).toBeVisible();

    // Verify toast message contains success text
    const successToast = page.getByText('Background sync completed successfully');
    await expect(successToast).toBeVisible();

    // Verify toast has success icon
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();

    // Verify toast has close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast is dismissible
    await closeButton.click();
    await expect(toastContainer).not.toBeVisible();
  });

  test('should display error toast notification when background sync fails', async ({ page }) => {
    // Setup: intercept the API call for background sync with error response
    await page.route('**/api/sync/background', (route) => {
      route.abort('failed');
    });

    // Verify toast container exists
    const toastContainer = page.getByRole('status');
    await expect(toastContainer).toBeVisible();

    // Verify toast message contains error text
    const errorToast = page.getByText('Background sync failed');
    await expect(errorToast).toBeVisible();

    // Verify toast has error icon
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify toast has close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast is dismissible
    await closeButton.click();
    await expect(toastContainer).not.toBeVisible();
  });
});
